const exaResults = $('Find Growth Signals').all().map(item => {
  return `
- Title: ${item.json.title || 'N/A'}
  URL: ${item.json.url || 'N/A'}
  Published Date: ${item.json.publishedDate || 'Unknown'}
  Summary: ${item.json.summary || item.json.text || 'No summary available.'}
  `;
}).join('\n');

return [{
  json: {
    ...$json,
    formatted_exa_evidence: exaResults
  }
}];

const raw = $('Synthesize Intelligence & Evidence').first().json.output?.[0]?.content?.[0]?.text || '';

let synthesis = {};
try {
  const cleaned = raw.replace(/```json\s?|```/g, '').trim();
  const jsonStart = cleaned.indexOf('{');
  const jsonEnd = cleaned.lastIndexOf('}');
  synthesis = JSON.parse(cleaned.substring(jsonStart, jsonEnd + 1));
} catch (error) {
  return [{
    json: {
      ...$json,
      icp_score: null,
      icp_tier: 'Needs Review',
      scoring_rationale: ['Research synthesis was not valid JSON'],
      icp_breakdown: [],
      parsed_synthesis: null
    }
  }];
}

const summary = String(synthesis.summary || '').toLowerCase();
const facts = JSON.stringify(synthesis.confirmed_facts || []).toLowerCase();
const combinedText = summary + ' ' + facts;

// With no summary and no confirmed facts we cannot judge any criterion:
// mark them "unknown" rather than "not met".
const hasEvidence = summary.trim().length > 0 || (synthesis.confirmed_facts || []).length > 0;

const breakdown = [];
function criterion(name, max, score, reasonMet, reasonNotMet) {
  const status = !hasEvidence ? 'unknown' : score > 0 ? 'met' : 'not_met';
  breakdown.push({
    criterion: name,
    score: hasEvidence ? score : 0,
    max,
    status,
    reason: status === 'unknown' ? 'Not enough research evidence to evaluate' : (score > 0 ? reasonMet : reasonNotMet)
  });
}

breakdown.push({ criterion: 'Baseline', score: 20, max: 20, status: 'met', reason: 'Starting score for every researched company' });

// 1. Industry fit (up to +35)
if (/saas|software|technology/i.test(combinedText)) {
  criterion('Industry Fit', 35, 35, 'Core vertical: SaaS/Technology', '');
} else if (/manufacturing|industrial|supplier|logistics/i.test(combinedText)) {
  criterion('Industry Fit', 35, 30, 'Target vertical: Manufacturing/Industrial/Logistics', '');
} else {
  criterion('Industry Fit', 35, 0, '', 'Not in a core or target vertical');
}

// 2. Digital opportunity (up to +25)
const workflowNeed = /workflow|automation|portal|integration|custom software/i.test(combinedText);
criterion('Digital Opportunity', 25, workflowNeed ? 25 : 0,
  'Workflow, automation, portal or integration need found',
  'No workflow or integration need found');

// 3. Growth signals (up to +20)
const growth = /growth|expanding|hiring|partnership|funding|acquisition/i.test(combinedText);
criterion('Growth Signals', 20, growth ? 20 : 0,
  'Growth, hiring, funding or partnership signals found',
  'No growth signals found');

const score = Math.min(Math.max(breakdown.reduce((sum, c) => sum + c.score, 0), 0), 100);

let tier = 'Low Fit';
if (score >= 80) {
  tier = 'High Fit';
} else if (score >= 55) {
  tier = 'Moderate Fit';
}

return [{
  json: {
    ...$json,
    icp_score: score,
    icp_tier: tier,
    scoring_rationale: breakdown.filter(c => c.criterion !== 'Baseline').map(c => `${c.criterion}: ${c.reason} (+${c.score})`),
    icp_breakdown: breakdown,
    parsed_synthesis: synthesis
  }
}];

// Validate the frontend request body: { input: string, refresh?: boolean }
const body = $input.first().json.body || {};
const input = typeof body.input === 'string' ? body.input.trim() : '';
const refresh = body.refresh === true;

if (input.length < 2 || input.length > 200) {
  return [{ json: { valid: false, error: 'Enter a company name or website domain (2-200 characters).' } }];
}

